  function hydrateIcons(root=document) { root.querySelectorAll('[data-icon]').forEach(el => { el.innerHTML=icon(el.dataset.icon); }); }
  function badge(task) {return `<span class="badge ${task.status}">${esc(statuses[task.status])}</span>`;}
  function action(label, actionName, primary=false, extra='') {return `<button type="button" class="button${primary?' primary':''}" data-action="${actionName}" ${extra}>${esc(label)}</button>`;}
  function pageHead(eyebrow,title,description,buttons='') {return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="head-actions">${buttons}</div></div>`;}
  function notify(text) {const toast=document.querySelector('#toast');toast.textContent=text;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),4800);}
  function record(text,detail,iconName='clock') {state.events.unshift({text,detail,icon:iconName});}
