  function settleRun(run='R-08'){if(run==='R-08'&&state.aggregate&&!['ready','applied'].includes(state.runStatus)&&runComplete()){state.runStatus='ready';state.runRevision++;record('R-08 · todas as tarefas validadas',`Candidato i${state.runRevision}; revise o diff completo antes da aplicação.`,'branch');}}
  const helpers=()=>({esc,icon,action,pageHead,showModal,closeModal,render,notify,record,modelLabel});
