    if(name==='plan'){showModal('Plano do objetivo',`<p>Plano ilustrativo aprovado pelo usuário. O primeiro alpha trabalha com tarefas definidas manualmente; o planejador autônomo é uma entrega posterior.</p><ol class="acceptance"><li>${icon('circle')}<span><strong>1. Fortalecer sessões</strong><br>OX-24 rotação · OX-25 revogação, independentes.</span></li><li>${icon('circle')}<span><strong>2. Validar destinos de login</strong><br>OX-26 aguarda uma decisão explícita.</span></li><li>${icon('circle')}<span><strong>3. Documentar o comportamento</strong><br>OX-27 depende dos resultados de OX-24 e OX-25.</span></li></ol><div class="form-actions">${action('Voltar ao trabalho','close-modal',true)}</div>`);return;}
