    if(name==='permission'&&task.status==='permission'){showModal('Permissão para esta tentativa',`<p>Solicitação de ${esc(task.id)} · tentativa ${task.attempt} · ${esc(task.account)}. Examine antes de decidir.</p><div class="snapshot">Comando ilustrativo: <code>npm test -- token-service</code><br>Diretório: ${esc(state.projectPath)}<br>Alcance: verificações do comportamento; ferramentas podem gravar caches.<br>Estado: não executado nesta simulação.</div><p>Recusar mantém o trabalho aguardando. Permitir libera somente esta solicitação.</p><div class="form-actions">${action('Recusar na demonstração','deny-permission')}${action('Permitir na demonstração','allow-permission',true)}</div>`);return;}
