    if(name==='cancel-unknown'){task.cancelRequested=true;task.status='unknown';record(`${task.id} · cancelamento solicitado sem confirmação`,'Término desconhecido. Reconciliar antes de preparar outra tentativa.','alert');closeModal();render();notify('Cancelamento sem confirmação. A tentativa permanece sob reconciliação.');return;}
