    if(name==='retry'&&task.status==='failed'){task.attempt++;configureAttempt(task);task.status='ready';record(`${task.id} · nova tentativa preparada`,`Tentativa ${task.attempt}; a anterior permanece no histórico.`,'reset');render();notify('Uma nova tentativa foi preparada; ainda não está em execução.');return;}
    if(name==='start'&&task.status==='ready'){if(state.aggregate&&(task.dependencies||[]).some(id=>state.tasks.find(t=>t.id===id)?.status!=='integrated')){notify('Esta etapa depende de OX-24 e OX-25 validadas no Run. Nenhuma execução foi iniciada.');return;}const c=state.connections.find(c=>c.id===task.connectionId);if(!c||!window.OrchestrixConnections.eligible(c)||!modelSupports(c,task.config.model)){notify('A conexão desta tentativa não está elegível. Inspecione Conexões; o trabalho e seu contexto foram preservados.');navigate('connections');return;}task.connectionSnapshot={id:c.id,name:c.name,provider:c.provider,status:c.status,authorizationRecord:c.identity.recordId,modality:c.modality,catalog:structuredClone(c.catalog)};task.status='running';record(`${task.id} · execução simulada iniciada`,`Tentativa ${task.attempt} · ${task.account}`,'play');render();return;}
    if(name==='resolve'){showModal('Definir destinos permitidos',`<p>OX-26 precisa de uma decisão do projeto. O exemplo usa caminhos locais como /conta; não há acesso a URLs.</p><form id="decision-form"><label class="form-label" for="destinations">Destinos após o login</label><input id="destinations" name="destinations" required maxlength="250" placeholder="/conta, /configuracoes"><div class="form-actions"><button class="button primary" type="submit">Registrar decisão simulada</button></div></form>`);return;}
