    if(name==='finish-correction'&&task.id==='OX-24'&&task.status==='running'){task.status='review';state.revision++;state.hasArtifact=true;state.artifactAttempt=task.attempt;state.checksFailed=false;state.runStatus='task-review';state.approvedRevision=null;record('OX-24 · correção e revisão simuladas concluídas',`Tentativa ${task.attempt} · novo artefato r${state.revision}`,'shield');render();notify('Novo artefato preparado. A revisão anterior não autoriza sua aplicação.');return;}
    if(name==='fail-check'&&artifactTask().status==='review'){state.checksFailed=true;record('OX-24 · verificação simulada falhou',`Artefato r${state.revision} · exit 1 · revogação esperada.`,'alert');render();notify('Falha de verificação simulada. O aceite da tarefa está bloqueado.');return;}
    if(name==='approve-task'){const t=artifactTask();if(t.status!=='review'||state.checksFailed)return;showModal('Validar esta tarefa no Run?',`<p>Aceitar este artefato integra a tarefa na branch interna de R-08. A aplicação em main será uma revisão separada.</p><div class="snapshot">Tarefa: <strong>OX-24</strong> · tentativa ${state.artifactAttempt}<br>Artefato: <code>r${state.revision} · ${artifactHash()}</code><br>Branch interna: <code>orchestrix/R-08 · ${state.runBase}</code></div><div class="form-actions">${action('Voltar','close-modal')}${action('Validar na demonstração','confirm-task',true,`data-snapshot="${state.revision}:${state.runBase}"`)}</div>`);return;}
    if(name==='approve'){const t=artifactTask();if(t.status!=='integrated'||state.runStatus!=='ready'||!runComplete())return;const snapshot=`${state.revision}:${state.runRevision}:${state.base}`;showModal('Aplicar o resultado de R-08?',`<p>Confirme a identidade do resultado e o destino. Esta ação modifica somente os dados em memória da demonstração.</p><div class="snapshot">Run: <strong>R-08</strong> · ${state.aggregate?runTasks().map(t=>esc(t.id)).join(', '):'OX-24'} validada(s)<br>Artefato: <code>r${state.revision} · ${artifactHash()}</code><br>Candidato: <code>i${state.runRevision}</code><br>Destino: <code>main · ${state.base}</code><br>Verificações: exemplos aprovados</div><p id="approval-error" class="error-note" role="alert"></p><div class="form-actions">${action('Simular candidato alterado','change-candidate')}${action('Simular base alterada','change-base')}${action('Aplicar na demonstração','confirm-apply',true,`data-snapshot="${snapshot}"`)}</div>`);return;}
    if(name==='change-candidate'&&state.runStatus==='ready'&&artifactTask().status==='integrated'){state.runRevision++;state.runStatus='conflict';state.conflictReason='candidate';state.approvedRevision=null;record('R-08 · candidato alterado',`Candidato i${state.runRevision}; confirmação anterior invalidada.`,'branch');render();if(modal.open){document.querySelector('#approval-error').textContent='O candidato mudou. Esta confirmação expirou; revalide e revise o resultado.';modal.querySelector('[data-action="confirm-apply"]').disabled=true;}return;}
    if(name==='change-base'&&state.runStatus!=='applied'&&artifactTask().status==='integrated'){state.base=state.base==='b9f87d3'?'c3a91f0':'d71ba25';state.runStatus='conflict';state.conflictReason='base';state.approvedRevision=null;record('R-08 · base de destino alterada',`Nova base ${state.base}; a aprovação da aplicação foi invalidada.`,'branch');render();if(modal.open&&document.querySelector('#approval-error')){document.querySelector('#approval-error').textContent='A base mudou. Esta confirmação expirou; revalide e revise o resultado.';modal.querySelector('[data-action="confirm-apply"]').disabled=true;}else notify('Mudança de base simulada. A aplicação está bloqueada até nova revisão.');return;}
